import { c as resolveOpenClawStateSqlitePath } from "./openclaw-state-db.paths-CmKkMYdo.mjs";
import { a as resolveSqliteDatabaseFilePaths } from "./sqlite-files-C0SkQ4cH.mjs";
import { x as assertOpenClawStateDatabaseForMaintenance } from "./openclaw-state-db-fast-path-B6pqnU-B.mjs";
import { r as clearOpenClawDatabaseQuarantine } from "./openclaw-quarantine-store-y55sQkrf.mjs";
import { a as clearOpenClawStateDatabaseOpenFailure, f as isOpenClawStateDatabaseOpen } from "./openclaw-state-db-cache-CcFsu-Ub.mjs";
import { n as assertOpenClawStateWriteAllowed } from "./openclaw-state-ownership-BlLRb_S-.mjs";
import { y as ensureOpenClawStatePermissions } from "./openclaw-state-db-CRNYrEn5.mjs";
import { i as withDoctorSqliteMaintenanceLock } from "./doctor-sqlite-maintenance-lock-Bxgu4S09.mjs";
import { n as compactDoctorSqliteFile } from "./doctor-sqlite-compact-CqbjbwKh.mjs";
import fs from "node:fs";
//#region src/commands/doctor-state-sqlite-compact.ts
/** Explicit doctor maintenance for the canonical shared state SQLite database. */
/** Compact only the canonical shared state database resolved for this invocation. */
async function runDoctorStateSqliteCompact(options = {}) {
	const env = options.env ?? process.env;
	const sqlitePath = resolveOpenClawStateSqlitePath(env);
	const stat = fs.lstatSync(sqlitePath, { throwIfNoEntry: false });
	if (!stat) return {
		mode: "compact",
		path: sqlitePath,
		reason: "missing",
		skipped: true
	};
	if (!stat.isFile()) throw new Error(`Canonical OpenClaw state database is not a regular file: ${sqlitePath}`);
	return await withDoctorSqliteMaintenanceLock({
		env,
		operation: "state SQLite compaction",
		protectedPaths: resolveSqliteDatabaseFilePaths(sqlitePath),
		run: (authority) => {
			authority.assertCurrent();
			if (isOpenClawStateDatabaseOpen()) throw new Error("The shared OpenClaw state database is already open in this process. Stop OpenClaw and retry.");
			return {
				...compactDoctorSqliteFile({
					afterSuccess: () => {
						if (!clearOpenClawDatabaseQuarantine(sqlitePath, { env })) throw new Error(`OpenClaw state database ${sqlitePath} was compacted, but its persisted quarantine record could not be cleared. Rerun openclaw doctor --fix so the database is not refused again.`);
						clearOpenClawStateDatabaseOpenFailure(sqlitePath);
						ensureOpenClawStatePermissions(sqlitePath, env);
					},
					sqlitePath,
					validateBeforeMutation: (database) => {
						authority.assertCurrent();
						assertOpenClawStateWriteAllowed({
							database,
							databasePath: sqlitePath,
							env
						});
						assertOpenClawStateDatabaseForMaintenance(database, { pathname: sqlitePath });
					}
				}),
				mode: "compact",
				path: sqlitePath,
				skipped: false
			};
		}
	});
}
//#endregion
export { runDoctorStateSqliteCompact };
